-- =====================================================================
-- PatriBâti — 08. Jeu de données de démonstration
-- ATTENTION : toutes ces données sont FICTIVES (biens, titres fonciers, NICAD,
-- montants, occupants, entreprises, litiges). Les localisations sont approximatives
-- et les emprises dessinées sont des rectangles schématiques.
-- Fichier généré par un script : ne pas le modifier à la main.
-- =====================================================================
SET search_path = patrimoine, ref, public;
BEGIN;










-- Les identifiants ont été fournis : on recale les séquences.
SELECT setval(pg_get_serial_sequence('patrimoine.assiette_fonciere', 'id'), (SELECT COALESCE(max(id), 1) FROM patrimoine.assiette_fonciere));
SELECT setval(pg_get_serial_sequence('patrimoine.bien', 'id'), (SELECT COALESCE(max(id), 1) FROM patrimoine.bien));
SELECT setval(pg_get_serial_sequence('patrimoine.batiment', 'id'), (SELECT COALESCE(max(id), 1) FROM patrimoine.batiment));
SELECT setval(pg_get_serial_sequence('patrimoine.litige', 'id'), (SELECT COALESCE(max(id), 1) FROM patrimoine.litige));
SELECT setval(pg_get_serial_sequence('patrimoine.document', 'id'), (SELECT COALESCE(max(id), 1) FROM patrimoine.document));

-- Le chargement initial ne doit pas figurer dans le journal d'audit.
TRUNCATE patrimoine.journal;
COMMIT;
